package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.AnnotatedField;
import com.fasterxml.jackson.databind.introspect.ClassIntrospector.MixInResolver;
import com.fasterxml.jackson.databind.util.Annotations;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.lang.annotation.Annotation;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.reflect.*;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import org.mockito.invocation.InvocationOnMock;
import org.mockito.stubbing.Answer;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * Unit tests for AnnotatedClass._addFieldMixIns
 */
public class AnnotatedClass__addFieldMixIns_TriageGen2Test {

    // Dummy annotation for testing
    @Retention(RetentionPolicy.RUNTIME)
    @interface TestAnnotation {}

    // Target class for mix-in testing
    public static class TargetClass {
        public String targetField;
        public int otherField;
    }

    // Mix-in class with various field types
    public static class MixInClass {
        @JsonProperty("targetField")
        public String mixinField;

        @TestAnnotation
        public int annotatedField;

        public String nonExistentField;

        public static String staticField;

        private String privateField;
    }

    // Subclass of MixIn to test ClassUtil.findSuperTypes logic (parents list)
    public static class SubMixIn extends MixInClass {
        @JsonProperty("subField")
        public String subField;
    }

    // A subclass to extend the hierarchy
    public static class TargetClassWithSubMix extends TargetClass {
        public String subField;
    }

    /**
     * Since _addFieldMixIns is protected, we use a Testable subclass to expose it.
     */
    private static class TestableAnnotatedClass extends AnnotatedClass {
        protected TestableAnnotatedClass(Class<?> cls, com.fasterxml.jackson.databind.introspect.AnnotationIntrospector aintr, com.fasterxml.jackson.databind.introspect.MixInResolver mir) {
            super(cls, aintr, mir);
        }

        @Override
        public void _addFieldMixIns(Class<?> targetClass, Class<?> mixInCls, Map<String, AnnotatedField> fields) {
            super._addFieldMixIns(targetClass, mixInCls, fields);
        }

        // We need to override _isIncludableField because it's a protected method in the parent class
        // or we rely on the real implementation if it's accessible.
        // Given the prompt, we assume we test the logic as is.
    }

    @Test
    public void testAddFieldsWithMixIn() throws Exception {
        // Setup
        com.fasterxml.jackson.databind.introspect.AnnotationIntrospector aintr = mock(com.fasterxml.jackson.databind.introspect.AnnotationIntrospector.class);
        com.fasterxml.jackson.databind.introspect.MixInResolver mir = mock(com.fasterxml.jackson.databind.introspect.MixInResolver.class);

        AnnotatedClass annotatedClass = AnnotatedClass.construct(TargetClass.class, aintr, mir);

        // We use reflection to call the protected method if we can't subclass easily, 
        // but here we use the Testable class.
        TestableAnnotatedClass testableClass = new TestableAnnotatedClass(TargetClass.class, aintr, mir);

        Map<String, AnnotatedField> fieldsMap = new HashMap<>();

        AnnotatedField targetFieldMock = mock(AnnotatedField.class);
        AnnotatedField annotatedFieldMock = mock(AnnotatedField.class);

        fieldsMap.put("targetField", targetFieldMock);
        fieldsMap.put("annotatedField", annotatedFieldMock);
        fieldsMap.put("subField", mock(AnnotatedField.class));

        // We need to spy on the class to verify _addOrOverrideAnnotations is called
        TestableAnnotatedClass spyClass = spy(testableClass);

        // Execute
        spyClass._addFieldMixIns(TargetClass.class, SubMixIn.class, fieldsMap);

        // Verify
        // 1. targetField should have annotations merged (from mixinField)
        verify(spyClass)._addOrOverrideAnnotations(eq(targetFieldMock), any());
        // 2. annotatedField should have annotations merged (from annotatedField)
        verify(spyClass)._addOrOverrideAnnotations(eq(annotatedFieldMock), any());
        // 3. nonExistentField in MixInClass is not in the map, so no call
        // 4. staticField should be ignored by _isIncludableField (assuming standard Jackson impl)
    }

    @Test
    public void testAddFieldsWithNoMatches() throws Exception {
        com.fasterxml.jackson.databind.introspect.AnnotationIntrospector aintr = mock(com.fasterxml.jackson.databind.introspect.AnnotationIntrospector.class);
        com.fasterxml.jackson.databind.introspect.MixInResolver mir = mock(com.fasterxml.jackson.databind.introspect.MixInResolver.class);

        TestableAnnotatedClass testableClass = new TestableAnnotatedClass(TargetClass.class, aintr, mir);
        TestableAnnotatedClass spyClass = spy(testableClass);

        Map<String, AnnotatedField> fieldsMap = new HashMap<>();
        fieldsMap.put("somethingElse", mock(AnnotatedField.class));

        spyClass._addFieldMixIns(TargetClass.class, MixInClass.class, fieldsMap);

        // Verify no annotations were added because names don't match
        verify(spyClass, never())._addOrOverrideAnnotations(any(), any());
    }

    @Test
    public void testAddFieldsWithEmptyMap() throws Exception {
        com.fasterxml.jackson.databind.introspect.AnnotationIntrospector aintr = mock(com.fasterxml.jackson.databind.introspect.AnnotationIntrospector.class);
        com.fasterxml.jackson.databind.introspect.MixInResolver mir = mock(com.fasterxml.jackson.databind.introspect.MixInResolver.class);

        TestableAnnotatedClass testableClass = new TestableAnnotatedClass(TargetClass.class, aintr, mir);
        TestableAnnotatedClass spyClass = spy(testableClass);

        Map<String, AnnotatedField> fieldsMap = new HashMap<>();

        spyClass._addFieldMixIns(TargetClass.class, MixInClass.class, fieldsMap);

        verify(spyClass, never())._addOrOverrideAnnotations(any(), any());
    }

    @Test
    public void testAddFieldsWithOnlyStaticOrSynthetic() throws Exception {
        // This test relies on _isIncludableField returning false for static/synthetic
        com.fasterxml.jackson.databind.introspect.AnnotationIntrospector aintr = mock(com.fasterxml.jackson.databind.introspect.AnnotationIntrospector.class);
        com.fasterxml.jackson.databind.introspect.MixInResolver mir = mock(com.fasterxml.jackson.databind.introspect.MixInResolver.class);

        TestableAnnotatedClass testableClass = new TestableAnnotatedClass(TargetClass.class, aintr, mir);
        TestableAnnotatedClass spyClass = spy(testableClass);

        Map<String, AnnotatedField> fieldsMap = new HashMap<>();
        AnnotatedField staticFieldMock = mock(AnnotatedField.class);
        fieldsMap.put("staticField", staticFieldMock);

        spyClass._addFieldMixIns(TargetClass.class, MixInClass.class, fieldsMap);

        // Since staticField is static, _isIncludableField should return false, 
        // so _addOrOverrideAnnotations should NOT be called.
        verify(spyClass, never())._addOrOverrideAnnotations(eq(staticFieldMock), any());
    }
}
